// Demo data is generated by running the real workflow engine, so every record
// carries a complete and consistent activity history.
import * as E from './engine.js';
import { makeCtx, SETTINGS_DEFAULT } from './ctx.js';
import { userById, DEPT_HEAD } from './data/people.js';

export const SCHEMA_VERSION = 3;

const DEF_ANS = {
  validation: { process: 'No', cleaning: 'No', equipment: 'No' },
  analytical: { method: 'No', equipment: 'No' },
  stability: { required: 'No' },
  computer: { validation: 'No' },
  safety: { operator: 'No', environment: 'No' },
  training: { departments: ['QAD'], trainingType: 'Read and Understand' },
  qad: { stabilityProtocol: 'No', vendor: 'No', qualityAgreement: 'No' },
};
const REVIEWER = { validation: 'u_rajesh', analytical: 'u_saurabh', stability: 'u_saurabh', computer: 'u_vivek', safety: 'u_kavita', qad: 'u_neha' };
const ORDER = ['pend_endorse', 'pend_screen', 'assess', 'reg', 'consol', 'qa', 'impl', 'closeout', 'closed'];

export function buildSeed(base = new Date()) {
  const counters = { cc: {}, draft: 2480 };
  const delegations = [{ id: 'DEL-1', fromId: 'u_vikram', toId: 'u_arjun', start: E.isoDate(E.addDays(base, -3)), end: E.isoDate(E.addDays(base, 14)), reason: 'Annual leave', status: 'Active' }];
  const settings = { ...SETTINGS_DEFAULT };
  const day = (n, h = 10) => { const d = E.addDays(base, n); d.setUTCHours(h, 5 * (Math.abs(n) % 11), 0, 0); return d > base ? new Date(base.getTime() - 60000 * (2 + (Math.abs(n * 7 + h) % 40))) : d; };
  const mk = (uid, n, h) => makeCtx(userById(uid), { delegations, settings, counters, now: day(n, h) });
  const future = (n) => E.isoDate(E.addDays(base, n));

  function build(spec, upTo, start) {
    // `start` = days ago the request was created; each step moves forward in time
    let t = -start;
    const step = () => (t += 1);
    const init = spec.initiator;
    let r = E.createDraft(mk(init, t, 9), spec.form);
    if (upTo === 'draft') return r;
    r = E.submit(r, mk(init, t, 11));
    if (upTo === 'pend_endorse') return r;
    r = E.endorse(r, mk(DEPT_HEAD[r.department], step(), 10), { decision: 'endorse', comment: spec.endorseNote || 'Endorsed. Business need confirmed.' });
    if (upTo === 'pend_screen') return r;
    r = E.screen(r, mk('u_priya', step(), 11), { decision: 'accept', checks: { complete: true, justified: true, noDuplicate: true }, remarks: spec.qaRemarks || '' });
    const plan = spec.assess || {};
    const keys = Object.keys(DEF_ANS);
    const partial = spec.partial || {};
    step();
    keys.forEach((k, i) => {
      const p = plan[k] || {};
      if (upTo === 'assess' && partial[k] === 'skip') return;
      if (upTo === 'assess' && partial[k] === undefined && spec.partial && !plan[k]) { /* default accept below */ }
      const uid = k === 'training' ? DEPT_HEAD[r.department] : REVIEWER[k];
      if (upTo === 'assess' && partial[k] === 'clarify') {
        r = E.assess(r, mk(uid, t, 12 + (i % 3)), k, { decision: 'clarify', clarificationText: partial.clarifyText, answers: { ...(DEF_ANS[k] || {}), ...(p.answers || {}) } });
        return;
      }
      r = E.assess(r, mk(uid, t + (i % 3 === 0 ? 0 : 1), 9 + i), k, {
        decision: p.decision || 'accept',
        answers: { ...DEF_ANS[k], ...(p.answers || {}) },
        comments: p.comments || '',
        actions: p.actions,
        justification: p.justification,
      });
    });
    if (upTo === 'assess' || upTo === 'reg-wait') return r;
    t += 2;
    r = E.regulatory(r, mk('u_meera', t, 11), spec.reg || { andaStatus: 'Not Applicable', applicable: 'Not Applicable', reporting: [], regActionRequired: false, clientRequired: false, comments: 'No regulatory filing impact identified.' });
    if (upTo === 'reg') return r;
    if (spec.clientEvidenceAt !== undefined) {
      r = E.uploadClientEvidence(r, mk(spec.reg.clientOwnerId, t + spec.clientEvidenceAt, 15), { fileName: spec.clientFile, reviewedBy: spec.clientReviewer, reviewDate: E.isoDate(day(t + spec.clientEvidenceAt)), comment: 'Approved without conditions.' });
    }
    t += 1;
    (spec.extraActions || []).forEach((a) => { r = E.addAction(r, mk(init, t, 10), a); });
    if (upTo === 'consol') return r;
    r = E.consolidate(r, mk(init, t, 14), { decision: 'submit' });
    if (upTo === 'qa') return r;
    t += 1;
    r = E.qaApprove(r, mk('u_neha', t, 11), { decision: 'approve', answers: spec.risk || { q1a: 'No', q1b: 'No', q1c: 'No', q1d: 'No', q2a: 'No' }, otherRisks: spec.otherRisks || '', comments: spec.riskComments || 'Risk assessed and acceptable with the listed actions.', dueDate: E.isoDate(E.addDays(day(t), 60)) });
    // implementation
    (spec.impl || []).forEach((u) => {
      t += u.after;
      const act = r.actions.find((a) => a.id === u.id);
      r = E.updateAction(r, mk(act.ownerId, t, 13), u.id, { status: u.status, comment: u.comment, evidenceName: u.evidence });
    });
    (spec.extra2 || []).forEach((f) => { r = f(r, mk, t, E); });
    if (upTo === 'impl') return r;
    t += 1;
    r = E.verify(r, mk(init, t, 10), { sopNumber: spec.sopNumber });
    if (upTo === 'closeout') return r;
    t += 1;
    const sug = E.suggestCloseout(r);
    r = E.closeout(r, mk('u_priya', t, 12), { decision: 'close', answers: { c1: 'Yes', c2: 'Yes', c3: 'Yes', c4: 'No', c5: 'No', c6: 'Yes', c7: sug.c7, c8: sug.c8 || 'Yes' }, comment: 'All requirements satisfied.' });
    return r;
  }

  const records = [];
  const f = (o) => ({ description: o.description || o.proposedChange, ...o });

  // 1. Closed – Test Method (Quality Control)
  records.push(build({
    initiator: 'u_pooja',
    form: f({ title: 'Revise HPLC assay method TM-021 – change mobile phase buffer', type: 'Test Method', currentDoc: 'TM-021 v03', proposedDoc: 'TM-021 v04', description: 'Revision of assay method TM-021 for Metformin HCl tablets.', currentState: 'Mobile phase uses phosphate buffer pH 3.0 with 18 min runtime.', proposedChange: 'Use phosphate buffer pH 2.8 with a shorter 12 min runtime.', justification: 'Improves peak symmetry and reduces runtime without affecting accuracy.' }),
    assess: {
      analytical: { decision: 'accept_action', answers: { method: 'Yes', equipment: 'No' }, comments: 'Method validation (robustness and specificity) required.', actions: [{ description: 'Execute method validation protocol for revised TM-021', ownerId: 'u_saurabh', due: future(-30) }] },
      training: { decision: 'accept_action', answers: { departments: ['QCS'], trainingType: 'Read and Understand' }, actions: [{ description: 'Train QC analysts on TM-021 v04', ownerId: 'u_pooja', due: future(-20) }] },
    },
    impl: [
      { id: 'ACT-01', after: 8, status: 'Completed', comment: 'Validation report approved; all acceptance criteria met.', evidence: 'TM-021_validation_report.pdf' },
      { id: 'ACT-02', after: 4, status: 'Completed', comment: 'Training records completed for all QC analysts.', evidence: 'TM-021_training_attendance.pdf' },
    ],
  }, 'closed', 70));

  // 2. Implementation in progress – vision cameras (client approval, overdue action, pending amendment)
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Replace end-of-life vision cameras on Packaging Line 3', type: 'Equipment/Facility/Utility', currentDoc: 'EQ-PKG-003 (Vision system, 2016)', proposedDoc: 'EQ-PKG-003A (Vision system, new)', description: 'Replace the end-of-life vision inspection cameras and software on Packaging Line 3.', currentState: 'Existing cameras are discontinued and give frequent false rejects.', proposedChange: 'Install new cameras with electronic batch reconciliation and audit trail.', justification: 'Eliminates false rejects, improves line speed by 15% and removes obsolescence risk.', layoutPlan: false }),
    assess: {
      validation: { decision: 'accept_action', answers: { process: 'No', cleaning: 'No', equipment: 'Yes' }, comments: 'Equipment qualification required before use.', actions: [{ description: 'Execute IQ/OQ for the new vision camera system on Packaging Line 3', ownerId: 'u_nikhil', due: future(12) }] },
      computer: { decision: 'accept_action', answers: { validation: 'Yes' }, comments: 'Computerized system validation needed (audit trail, access control).', actions: [{ description: 'Validate vision software – audit trail, access control, backup', ownerId: 'u_vivek', due: future(20) }] },
      training: { decision: 'accept_action', answers: { departments: ['OPS', 'QAD'], trainingType: 'On-The-Job Training' }, actions: [{ description: 'Train line operators on the revised vision inspection procedure', ownerId: 'u_karan', due: future(25) }] },
      qad: { decision: 'accept_action', answers: { stabilityProtocol: 'No', vendor: 'Yes', qualityAgreement: 'No' }, comments: 'Camera supplier must be added to the approved vendor list.', actions: [{ description: 'Add the camera supplier to the approved vendor list', ownerId: 'u_priya', due: future(-4) }] },
    },
    reg: { andaStatus: 'Not Applicable', applicable: 'Not Applicable', reporting: [], regActionRequired: false, clientRequired: true, clientName: 'Veridian Therapeutics', clientOwnerId: 'u_sonal', clientDue: future(-5), comments: 'Client notification required for equipment change on their product line.' },
    clientEvidenceAt: 1, clientFile: 'Veridian_approval_signed.pdf', clientReviewer: 'Dr. A. Fischer (Veridian QA)',
    extraActions: [{ description: 'Update the line clearance checklist for the new vision system', ownerId: 'u_karan', due: future(15) }],
    risk: { q1a: 'No', q1b: 'Yes', q1c: 'No', q1d: 'Yes', q2a: 'No' },
    impl: [
      { id: 'ACT-06', after: 3, status: 'Completed', comment: 'Checklist revised and approved by QA.', evidence: 'Line_clearance_checklist_rev2.pdf' },
      { id: 'ACT-01', after: 1, status: 'In Progress', comment: 'IQ completed; OQ scheduled.' },
      { id: 'ACT-02', after: 1, status: 'In Progress', comment: 'Validation plan approved; execution started.' },
    ],
    extra2: [(r, mk, t, EE) => EE.requestAmendment(r, mk('u_ananya', -1), { description: 'Add periodic recalibration schedule for the new vision cameras', reason: 'Calibration frequency was not defined in the original plan.', ownerId: 'u_nikhil', due: future(35) })],
  }, 'impl', 40));

  // 3. Pending QA closeout – SOP revision
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Revise SOP-MFG-012 – Line clearance procedure', type: 'SOP', currentDoc: 'SOP-MFG-012 v04', proposedDoc: 'SOP-MFG-012 v05', description: 'Revision of the line clearance SOP.', currentState: 'The SOP does not cover clearance of printed packaging components.', proposedChange: 'Add clearance steps for printed packaging components and a second-person check.', justification: 'Closes an audit observation and reduces mix-up risk.' }),
    assess: { training: { decision: 'accept_action', answers: { departments: ['OPS', 'QAD'], trainingType: 'Read and Understand' }, actions: [{ description: 'Train packaging and production staff on SOP-MFG-012 v05', ownerId: 'u_karan', due: future(-6) }] } },
    extraActions: [{ description: 'Issue SOP-MFG-012 v05 as effective and retrieve superseded copies', ownerId: 'u_priya', due: future(-8) }],
    impl: [
      { id: 'ACT-02', after: 6, status: 'Completed', comment: 'SOP v05 effective; old copies retrieved.', evidence: 'SOP-MFG-012_v05_effective.pdf' },
      { id: 'ACT-01', after: 1, status: 'Completed', comment: 'Training completed for 24 staff.', evidence: 'Training_attendance_SOP-MFG-012.pdf' },
    ],
    sopNumber: 'SOP-MFG-012 v05 (approved by QAD)',
  }, 'closeout', 36));

  // 4. Pending QA approval – client evidence missing (gate demonstration)
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Change supplier of primary packaging film for Tablet Blister Line', type: 'Vendor', currentDoc: 'Supplier: FilmPack Ltd (Spec PK-110)', proposedDoc: 'Supplier: AlphaFoil Ltd (Spec PK-110)', description: 'Qualify AlphaFoil Ltd as an additional supplier of blister film.', currentState: 'Single source supplier with recurring delivery delays.', proposedChange: 'Introduce a second qualified supplier with the same specification.', justification: 'Secures supply continuity.' }),
    assess: { qad: { decision: 'accept_action', answers: { stabilityProtocol: 'Yes', vendor: 'Yes', qualityAgreement: 'Yes' }, comments: 'Vendor qualification and quality agreement update needed.', actions: [{ description: 'Complete vendor qualification audit for AlphaFoil Ltd', ownerId: 'u_priya', due: future(30) }] }, validation: { decision: 'accept_action', answers: { process: 'Yes', cleaning: 'No', equipment: 'No' }, actions: [{ description: 'Run three packaging trial batches with the new film', ownerId: 'u_karan', due: future(35) }] } },
    reg: { andaStatus: 'Approved', applicable: 'Applicable', reporting: ['Supplement-Changes being affected in 30 days'], reference: 'ANDA 214567', regActionRequired: true, clientRequired: true, clientName: 'Veridian Therapeutics', clientOwnerId: 'u_sonal', clientDue: future(10), actions: [{ description: 'Prepare and file the CBE-30 supplement for ANDA 214567', ownerId: 'u_meera', due: future(25) }], comments: 'Packaging component change – supplement required.' },
  }, 'qa', 12));

  // 5. Pending consolidation (initiator task) – Quality Control initiator
  records.push(build({
    initiator: 'u_pooja',
    form: f({ title: 'Upgrade environmental monitoring software to version 6.2', type: 'Computer System', currentDoc: 'EMS v5.4', proposedDoc: 'EMS v6.2', description: 'Upgrade of the environmental monitoring software.', currentState: 'v5.4 is out of vendor support.', proposedChange: 'Upgrade to v6.2 with revalidation.', justification: 'Vendor support ends this year.' }),
    assess: { computer: { decision: 'accept_action', answers: { validation: 'Yes' }, actions: [{ description: 'Execute validation (IQ/OQ/PQ) for EMS v6.2', ownerId: 'u_vivek', due: future(40) }] } },
  }, 'consol', 9));

  // 6. Regulatory assessment pending
  records.push(build({
    initiator: 'u_pooja',
    form: f({ title: 'Tighten specification limit for raw material RM-045 assay', type: 'Specification', currentDoc: 'SPEC-RM-045 v02', proposedDoc: 'SPEC-RM-045 v03', description: 'Narrow the assay limit of RM-045.', currentState: 'Assay limit is 95.0–105.0%.', proposedChange: 'Assay limit 98.0–102.0%.', justification: 'Supplier data show consistent results; tighter control reduces batch variability.' }),
  }, 'reg-wait', 7));

  // 7. Departmental assessment in progress (clarification + pending)
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Update batch record BMR-114 for the Tablet Compression stage', type: 'Batch Record', currentDoc: 'BMR-114 v06', proposedDoc: 'BMR-114 v07', description: 'Add in-process hardness check frequency to the BMR.', currentState: 'Hardness is checked hourly.', proposedChange: 'Check hardness every 30 minutes for the first two hours.', justification: 'Detects compression drift earlier.' }),
    assess: { validation: { decision: 'accept_action', answers: { process: 'No', cleaning: 'No', equipment: 'Not Applicable' }, comments: 'No validation impact.', actions: [{ description: 'Update the in-process control instruction sheet', ownerId: 'u_karan', due: future(20) }] }, computer: { decision: 'accept' } },
    partial: { analytical: 'clarify', clarifyText: 'Which hardness tester and calibration status will be used for the 30-minute checks?', stability: 'skip', safety: 'skip', training: 'skip', qad: 'skip' },
  }, 'assess', 4));

  // 8. Pending QA screening
  records.push(build({
    initiator: 'u_pooja',
    form: f({ title: 'Update stability protocol SP-009 storage conditions', type: 'Protocol/Report', currentDoc: 'SP-009 v01', proposedDoc: 'SP-009 v02', description: 'Revise storage conditions in the stability protocol.', currentState: 'Samples are stored at 25°C/60% RH only.', proposedChange: 'Add 30°C/65% RH intermediate condition.', justification: 'Required by the updated regulatory guideline.' }),
  }, 'pend_screen', 2));

  // 9. Pending Department Head endorsement
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Add new cleaning agent to the CIP cycle of Granulator GR-02', type: 'Other', otherType: 'Cleaning procedure', currentDoc: 'CLN-GR-02 v03', proposedDoc: 'CLN-GR-02 v04', description: 'Introduce an alkaline detergent in the CIP cycle.', currentState: 'Only purified water rinse is used.', proposedChange: 'Add an alkaline wash followed by a water rinse.', justification: 'Improves removal of residue on difficult-to-clean surfaces.' }),
  }, 'pend_endorse', 1));

  // 10. Draft
  records.push(build({
    initiator: 'u_ananya',
    form: f({ title: 'Relocate the reserve sample storage cabinet', type: 'Equipment/Facility/Utility', description: 'Move the reserve sample cabinet to the new QC annex.', currentState: '', proposedChange: '', justification: '' }),
  }, 'draft', 0));

  // 11. Rejected at screening (duplicate)
  {
    let r = build({
      initiator: 'u_pooja',
      form: f({ title: 'Revise TM-021 mobile phase buffer (duplicate request)', type: 'Test Method', description: 'Duplicate of an existing request.', currentState: 'See existing request.', proposedChange: 'See existing request.', justification: 'Duplicate.' }),
    }, 'pend_screen', 20);
    r = E.screen(r, mk('u_priya', -18, 11), { decision: 'reject', comment: 'Duplicate of CC26001, which is already closed. No separate change control needed.' });
    records.push(r);
  }

  // handle 'reg-wait' marker: build() returned after assessments complete
  return { schema: SCHEMA_VERSION, counters, delegations, settings, records: records.map(fixRegWait), admin: [{ id: 'ad-1', at: day(-60).toISOString(), actor: 'Rohit Sinha', action: 'Demo data initialised', detail: 'System baseline created.' }], seededAt: base.toISOString() };
}
const fixRegWait = (r) => r;
